# Slow: row-level Python UDF
from pyspark.sql.functions import udf
from pyspark.sql.types import DoubleType

@udf(DoubleType())
def score_row(amount, category):
    return float(amount) * 1.5 if category == 'premium' else float(amount)

# Fast: Pandas UDF (vectorized)
import pandas as pd
from pyspark.sql.functions import pandas_udf

@pandas_udf(DoubleType())
def score_vectorized(amount: pd.Series, category: pd.Series) -> pd.Series:
    return amount.where(category != 'premium', amount * 1.5)

def upsert_to_delta(batch_df, batch_id):
    (
        DeltaTable.forName(spark, "users")
        .alias("t")
        .merge(batch_df.alias("s"), "t.user_id = s.user_id")
        .whenMatchedUpdate(set={
            "name":       col("s.name"),
            "updated_at": col("s.updated_at")
        })
        .whenNotMatchedInsert(values={
            "user_id":    col("s.user_id"),
            "name":       col("s.name"),
            "updated_at": col("s.updated_at")
        })
        .execute()
    )

streaming_df.writeStream.foreachBatch(upsert_to_delta).start()
